from pathlib import Path
root=Path('/workspace/repo-vul/src-vul/hdf5/src')
for term in ['H5Z__filter_deflate','filter pipeline','H5Z_pipeline','H5D__chunk_lock','H5D__chunk_read']:
 print('\nTERM',term)
 for p in root.rglob('*.c'):
  txt=p.read_text(errors='ignore')
  if term in txt:
   for i,l in enumerate(txt.splitlines(),1):
    if term in l:
     print(p.name, i, l.strip())
